markMutating(meta.command("observe [type] [content]"))
  .option("--workflow <ref>", "Reference to workflow")
  .option("--author <author>", "Author of observation")
  .option("--from-inbox <ref>", "Convert inbox item to observation")
  .option("--type <type>", "Override type when using --from-inbox")
  .action(async (type, content, options) => {
    const ctx = await initContext();

    // Case 1: Convert from inbox item
    if (options.fromInbox) {
      const inboxItems = await loadInboxItems(ctx);
      const item = findInboxItemByRef(inboxItems, options.fromInbox);
      const observationType = (options.type || "idea") as ObservationType;

      const observation = createObservation(
        observationType,
        item.text,  // Use inbox item text as content
        {
          workflow_ref: options.workflow,
          author: options.author,
          configAuthor: ctx.config?.identity?.author,
        },
      );

      await saveObservation(ctx, observation);
      await deleteInboxItem(ctx, item._ulid);
      await commitIfShadow(
        ctx.shadow,
        "meta-observe-from-inbox",
        observation._ulid.substring(0, 8),
        `Convert inbox item to ${observationType} observation`,
      );

      output(observation, () =>
        success(`Created observation: ${shortUlid}`),
      );
    }
    // Case 2: Direct observation creation
    else {
      const observation = createObservation(type, content, { ... });
      await saveObservation(ctx, observation);
      await commitIfShadow(ctx.shadow, "meta-observe", shortUlid, type);
      output(observation, () => success(`Created observation: ${shortUlid}`));
    }
  });
