   293→
   294→  // Show timestamps (AC-1)
   295→  console.log(chalk.gray(`${indent}Created: ${task.created_at}`));
   296→  if (task.started_at) {
   297→    console.log(chalk.gray(`${indent}Started: ${task.started_at}`));
   298→  }
   299→  if (task.completed_at) {
   300→    console.log(chalk.gray(`${indent}Completed: ${task.completed_at}`));
   301→  }
   302→
   303→  // Show notes count and most recent note (AC-1, AC-3)
   304→  if (task.notes && task.notes.length > 0) {
   305→    const mostRecent = task.notes[task.notes.length - 1];
   306→    const preview = getFirstLine(mostRecent.content, 50);
   307→    console.log(
   308→      chalk.gray(`${indent}Notes: ${task.notes.length} (latest: "${preview}")`),
   309→    );
   310→  }
   311→
   312→  // Show pending todos count (AC-1, AC-3)
   313→  if (task.todos && task.todos.length > 0) {
   314→    const pendingCount = task.todos.filter((t) => !t.done).length;
   315→    if (pendingCount > 0) {
   316→      console.log(chalk.gray(`${indent}Pending todos: ${pendingCount}`));
   317→    }
   318→  }
   319→
   320→  // Show spec context (AC-5)
   321→  if (task.spec_ref && index) {
   322→    const result = index.resolve(task.spec_ref);
   323→    if (result.ok) {
   324→      const spec = result.item;
   325→      const specName =
   326→        "title" in spec
   327→          ? spec.title
   328→          : "name" in spec
   329→            ? spec.name
   330→            : "id" in spec
   331→              ? spec.id
   332→              : task.spec_ref;
   333→      console.log(chalk.gray(`${indent}Spec: ${task.spec_ref}`));
   334→      console.log(chalk.cyan(`${indent}  ${specName}`));
   335→
   336→      // Show spec description if available
   337→      if ("description" in spec && spec.description) {
   338→        const descPreview = getFirstLine(spec.description as string, 70);
   339→        console.log(chalk.gray(`${indent}  ${descPreview}`));
   340→      }
   341→
   342→      // Show acceptance criteria if available
   343→      if (
   344→        "acceptance_criteria" in spec &&
   345→        Array.isArray(spec.acceptance_criteria)
   346→      ) {
   347→        const ac = spec.acceptance_criteria;
   348→        if (ac.length > 0) {
   349→          console.log(
   350→            chalk.gray(`${indent}  Acceptance Criteria: ${ac.length}`),
   351→          );
   352→          // Show first AC as preview
   353→          const firstAC = ac[0];
   354→          if (
   355→            typeof firstAC === "object" &&
   356→            firstAC !== null &&
   357→            "id" in firstAC
   358→          ) {
   359→            console.log(
   360→              chalk.gray(`${indent}    [${firstAC.id}] ${firstAC.then}`),
   361→            );
   362→          }
   363→        }
   364→      }
   365→    }
   366→  }
   367→
   368→  // Show tags and dependencies if present
   369→  if (task.tags && task.tags.length > 0) {
   370→    console.log(chalk.gray(`${indent}Tags: ${task.tags.join(", ")}`));
   371→  }
   372→  if (task.depends_on && task.depends_on.length > 0) {
   373→    console.log(
   374→      chalk.gray(`${indent}Depends on: ${task.depends_on.join(", ")}`),
   375→    );
   376→  }
   377→}
   378→
   379→/**
   380→ * Format automation status as a colored label
   381→ * AC: @task-automation-eligibility ac-14
   382→ */
   383→function formatAutomationStatus(automation: string | undefined): string {
   384→  if (!automation) {
   385→    return chalk.gray("[unassessed]");
   386→  }
   387→  switch (automation) {
   388→    case "eligible":
   389→      return chalk.green("[eligible]");
   390→    case "needs_review":
   391→      return chalk.yellow("[needs_review]");
   392→    case "manual_only":
   393→      return chalk.red("[manual_only]");
   394→    default:
   395→      return chalk.gray(`[${automation}]`);
   396→  }
   397→}
   398→
   399→/**
   400→ * Format a list of tasks with automation status
   401→ * AC: @task-automation-eligibility ac-14
   402→ */
   403→export function formatTaskListWithAutomation(
   404→  tasks: Task[],
   405→  verbose = false,
   406→  index?: ReferenceIndex,
   407→  grepPattern?: string,
   408→  full = false,
   409→): void {
   410→  if (tasks.length === 0) {
   411→    console.log(summaries.noTasks);
   412→    return;
   413→  }
   414→
   415→  for (const task of tasks) {
   416→    const ref = formatTaskRef(task, index);
   417→    const status = statusColor(task.status)(`[${task.status}]`);
   418→    const priority =
   419→      task.priority <= 2
   420→        ? chalk.red(`P${task.priority}`)
   421→        : chalk.gray(`P${task.priority}`);
   422→    const automationLabel = formatAutomationStatus(task.automation);
   423→
   424→    let line = `${ref} ${status} ${priority} ${automationLabel} ${task.title}`;
   425→
   426→    if (verbose && !full) {
   427→      if (task.spec_ref) {
   428→        line += chalk.gray(` (spec: ${task.spec_ref})`);
   429→      }
   430→      if (task.depends_on.length > 0) {
   431→        line += chalk.gray(` deps: [${task.depends_on.join(", ")}]`);
   432→      }
   433→      if (task.tags.length > 0) {
   434→        line += chalk.cyan(` #${task.tags.join(" #")}`);
   435→      }
   436→    }
   437→
   438→    console.log(line);
   439→
   440→    // Show matched fields if grep pattern provided
   441→    if (grepPattern) {
   442→      const match = grepItem(
   443→        task as unknown as Record<string, unknown>,
   444→        grepPattern,
   445→      );
   446→      if (match && match.matchedFields.length > 0) {
   447→        console.log(
   448→          chalk.gray(
   449→            `    matched: ${formatMatchedFields(match.matchedFields)}`,
   450→          ),
   451→        );
   452→      }
   453→    } else if (full) {
   454→      formatFullModeContext(task, index);
   455→    } else {
   456→      // Show context line: first line of description (if present)
   457→      const context = getFirstLine(task.description);
   458→      if (context) {
   459→        console.log(chalk.gray(`    ${context}`));
   460→      }
   461→    }
   462→  }
   463→
   464→  console.log(summaries.taskCount(tasks.length));
   465→}
   466→
   467→/**
   468→ * Format a list of tasks
   469→ */
   470→export function formatTaskList(
   471→  tasks: Task[],
   472→  verbose = false,
   473→  index?: ReferenceIndex,
   474→  grepPattern?: string,
   475→  full = false,
   476→): void {
   477→  if (tasks.length === 0) {
   478→    console.log(summaries.noTasks);
   479→    return;
   480→  }
   481→
   482→  for (const task of tasks) {
   483→    console.log(formatTask(task, verbose, index, full));
   484→
   485→    // Show matched fields if grep pattern provided
   486→    if (grepPattern) {
   487→      const match = grepItem(
   488→        task as unknown as Record<string, unknown>,
   489→        grepPattern,
   490→      );
   491→      if (match && match.matchedFields.length > 0) {
   492→        console.log(
   493→          chalk.gray(
   494→            `    matched: ${formatMatchedFields(match.matchedFields)}`,
   495→          ),
   496→        );
   497→      }
   498→    } else if (full) {
   499→      // AC: @task-list-verbose ac-1 - Full mode shows richer context
   500→      formatFullModeContext(task, index);
   501→    } else {
   502→      // Show context line: first line of description (if present)
   503→      const context = getFirstLine(task.description);
   504→      if (context) {
   505→        console.log(chalk.gray(`    ${context}`));
   506→      }
   507→    }
   508→  }
   509→
   510→  console.log(summaries.taskCount(tasks.length));
   511→}
   512→
   513→export interface FormatTaskDetailsOptions {
   514→  /** Show all notes including superseded ones (default: false) */
   515→  showAllNotes?: boolean;
   516→}
   517→
   518→/**
   519→ * Format task details
   520→ */
   521→export function formatTaskDetails(
   522→  task: Task,
   523→  index?: ReferenceIndex,
   524→  options: FormatTaskDetailsOptions = {},
   525→): void {
   526→  console.log(chalk.bold(task.title));
   527→  console.log(chalk.gray("─".repeat(40)));
   528→  console.log(`${fieldLabels.ulid}      ${task._ulid}`);
   529→  if (task.slugs.length > 0) {
   530→    console.log(`${fieldLabels.slugs}     ${task.slugs.join(", ")}`);
   531→  }
   532→  console.log(`${fieldLabels.type}      ${task.type}`);
   533→  console.log(
   534→    `${fieldLabels.status}    ${statusColor(task.status)(task.status)}`,
   535→  );
   536→  console.log(`${fieldLabels.priority}  ${task.priority}`);
   537→
   538→  // AC: @task-automation-eligibility ac-17 - show automation status
   539→  const automationDisplay = task.automation || "unassessed";
   540→  const automationColor =
   541→    task.automation === "eligible"
   542→      ? chalk.green
   543→      : task.automation === "needs_review"
   544→        ? chalk.yellow
   545→        : task.automation === "manual_only"
   546→          ? chalk.red
   547→          : chalk.gray;
   548→  console.log(
   549→    `${fieldLabels.automation} ${automationColor(automationDisplay)}`,
   550→  );
   551→
   552→  if (task.description?.trim()) {
   553→    console.log(`\n${sectionHeaders.description}`);
   554→    const desc = task.description.trim();
   555→    for (const line of desc.split("\n")) {
   556→      console.log(`  ${line}`);
   557→    }
   558→  }
   559→
   560→  if (task.spec_ref) {
   561→    console.log(`${fieldLabels.specRef}  ${task.spec_ref}`);
   562→  }
   563→
   564→  // AC: @plan-derive ac-6 - display plan_ref
   565→  if (task.plan_ref) {
   566→    console.log(`Plan ref:  ${task.plan_ref}`);
   567→  }
   568→
   569→  if (task.depends_on.length > 0) {
   570→    if (index) {
   571→      console.log(fieldLabels.depends);
   572→      for (const ref of task.depends_on) {
   573→        const result = index.resolve(ref);
   574→        if (result.ok) {
   575→          const item = result.item;
   576→          const status =
   577→            "status" in item && typeof item.status === "string"
   578→              ? statusColor(item.status as TaskStatus)(`[${item.status}]`)
   579→              : chalk.gray("[spec]");
   580→          // Handle both spec items (with title) and meta items (with name or id)
   581→          const itemName =
   582→            "title" in item
   583→              ? item.title
   584→              : "name" in item
   585→                ? item.name
   586→                : "id" in item
   587→                  ? item.id
   588→                  : ref;
   589→          console.log(`  ${ref} ${chalk.gray("→")} ${itemName} ${status}`);
   590→        } else {
   591→          console.log(`  ${ref} ${chalk.red("(unresolved)")}`);
   592→        }
   593→      }
   594→    } else {
   595→      console.log(`${fieldLabels.depends}   ${task.depends_on.join(", ")}`);
   596→    }
   597→  }
   598→
   599→  if (task.blocked_by.length > 0) {
   600→    console.log(
   601→      chalk.red(`${fieldLabels.blocked}   ${task.blocked_by.join(", ")}`),
   602→    );
   603→  }
   604→
   605→  if (task.tags.length > 0) {
   606→    console.log(`${fieldLabels.tags}      ${task.tags.join(", ")}`);
   607→  }
   608→
   609→  console.log(`${fieldLabels.created}   ${task.created_at}`);
   610→  if (task.started_at) {
   611→    console.log(`${fieldLabels.started}   ${task.started_at}`);
   612→  }
   613→  if (task.completed_at) {
   614→    console.log(`${fieldLabels.completed} ${task.completed_at}`);
   615→  }
   616→
   617→  // Show resolved spec information
   618→  if (task.spec_ref && index) {
   619→    const result = index.resolve(task.spec_ref);
   620→    if (result.ok) {
   621→      const spec = result.item;
   622→      console.log(`\n${sectionHeaders.specContext}`);
   623→      // Handle both spec items (with title) and meta items (with name)
   624→      const specName =
   625→        "title" in spec
   626→          ? spec.title
   627→          : "name" in spec
   628→            ? spec.name
   629→            : "id" in spec
   630→              ? spec.id
   631→              : task.spec_ref;
   632→      console.log(chalk.cyan(specName));
   633→      if ("type" in spec && spec.type) {
   634→        console.log(chalk.gray(`${fieldLabels.type} ${spec.type}`));
   635→      }
   636→      // Show implementation status
   637→      if ("status" in spec && spec.status && typeof spec.status === "object") {
   638→        const status = spec.status as {
   639→          maturity?: string;
   640→          implementation?: string;
   641→        };
   642→        if (status.implementation) {
   643→          const implColor =
   644→            status.implementation === "verified"
   645→              ? chalk.green
   646→              : status.implementation === "implemented"
   647→                ? chalk.cyan
   648→                : status.implementation === "in_progress"
   649→                  ? chalk.yellow
   650→                  : chalk.gray;
   651→          console.log(
   652→            chalk.gray(fieldLabels.implementation) +
   653→              implColor(status.implementation),
   654→          );
   655→        }
   656→      }
   657→      if ("description" in spec && spec.description) {
   658→        console.log(chalk.gray(fieldLabels.description));
   659→        // Indent description lines
   660→        const desc = String(spec.description).trim();
   661→        for (const line of desc.split("\n")) {
   662→          console.log(chalk.gray(`  ${line}`));
   663→        }
   664→      }
   665→      if (
   666→        "acceptance_criteria" in spec &&
   667→        Array.isArray(spec.acceptance_criteria) &&
   668→        spec.acceptance_criteria.length > 0
   669→      ) {
   670→        console.log(chalk.gray(fieldLabels.acceptanceCriteria));
   671→        for (const ac of spec.acceptance_criteria) {
   672→          if (ac && typeof ac === "object" && "id" in ac) {
   673→            const acObj = ac as {
   674→              id: string;
   675→              given?: string;
   676→              when?: string;
   677→              then?: string;
   678→            };
   679→            console.log(chalk.gray(`  [${acObj.id}]`));
   680→            if (acObj.given)
   681→              console.log(chalk.gray(`    Given: ${acObj.given}`));
   682→            if (acObj.when) console.log(chalk.gray(`    When: ${acObj.when}`));
   683→            if (acObj.then) console.log(chalk.gray(`    Then: ${acObj.then}`));
   684→          }
   685→        }
   686→      }
   687→      // Show traceability if present
   688→      if (
   689→        "traceability" in spec &&
   690→        spec.traceability &&
   691→        typeof spec.traceability === "object"
   692→      ) {
   693→        const trace = spec.traceability as {
   694→          implementation?: Array<{
   695→            path: string;
   696→            function?: string;
   697→            lines?: string;
   698→          }>;
   699→          tests?: Array<{ path: string }>;
   700→          commits?: string[];
   701→          issues?: string[];
   702→        };
   703→        const hasTrace =
   704→          trace.implementation?.length ||
   705→          trace.tests?.length ||
   706→          trace.commits?.length ||
   707→          trace.issues?.length;
   708→        if (hasTrace) {
   709→          console.log(chalk.gray(fieldLabels.traceability));
   710→          if (trace.implementation?.length) {
   711→            for (const impl of trace.implementation) {
   712→              let loc = `  Code: ${impl.path}`;
   713→              if (impl.function) loc += `::${impl.function}`;
   714→              if (impl.lines) loc += `:${impl.lines}`;
   715→              console.log(chalk.gray(loc));
   716→            }
   717→          }
   718→          if (trace.tests?.length) {
   719→            for (const test of trace.tests) {
   720→              console.log(chalk.gray(`  Test: ${test.path}`));
   721→            }
   722→          }
   723→          if (trace.commits?.length) {
   724→            console.log(chalk.gray(`  Commits: ${trace.commits.join(", ")}`));
   725→          }
   726→          if (trace.issues?.length) {
   727→            console.log(chalk.gray(`  Issues: ${trace.issues.join(", ")}`));
   728→          }
   729→        }
   730→      }
   731→    }
   732→  }
   733→
   734→  if (task.notes.length > 0) {
   735→    // Filter superseded notes unless showAllNotes is true
   736→    const notesToShow = options.showAllNotes
   737→      ? task.notes
   738→      : filterSupersededNotes(task.notes);
   739→    const hiddenCount = task.notes.length - notesToShow.length;
   740→
   741→    console.log(`\n${sectionHeaders.notes}`);
   742→    for (const note of notesToShow) {
   743→      const author = note.author || "unknown";
   744→      // Mark if this note supersedes another
   745→      const supersededLabel = note.supersedes ? chalk.gray(" (supersedes earlier note)") : "";
   746→      console.log(chalk.gray(`[${note.created_at}] ${author}:`) + supersededLabel);
   747→      console.log(note.content);
   748→    }
   749→
   750→    // Show count of hidden notes if any
   751→    if (hiddenCount > 0) {
   752→      console.log(chalk.gray(`\n(${hiddenCount} superseded note${hiddenCount > 1 ? "s" : ""} hidden - use --all to show)`));
   753→    }
   754→  }
   755→
   756→  if (task.todos.length > 0) {
   757→    console.log(`\n${sectionHeaders.todos}`);
   758→    for (const todo of task.todos) {
   759→      const check = todo.done ? chalk.green("✓") : chalk.gray("○");
   760→      const text = todo.done ? chalk.strikethrough.gray(todo.text) : todo.text;
   761→      console.log(`${check} [${todo.id}] ${text}`);
   762→    }
   763→  }
   764→}
