describe("triage JSON output trait compliance", () => {
  // AC: @trait-json-output ac-3
  it("should return JSON error on failure in JSON mode", () => {
    const result = kspec(
      'triage record @NOTEXIST --action promote --reasoning "test" --json',
      tempDir,
