            console.log(`  ${record._ulid.slice(0, 8)} (${age}${decidedBy}) ${record.status}${action}`);
            console.log(`    ${snapshot}`);
            console.log("");
          }
        });
      } catch (err) {
        error("Failed to list triage records", err);
        process.exit(EXIT_CODES.ERROR);
